let currentFilter = 'todos';
let bibleFilter = 'hoy';
let promiseView = 'todas';
let selectedPromiseCategory = '';
const STORAGE_SCHEMA_VERSION = 1;
const CURRENT_EDITION = window.JARDIN_APP?.currentEdition || 'agosto2026';
const STORAGE_PREFIX = `jardin:${CURRENT_EDITION}:`; // edición activa; no cambia datos de otros meses
const MONTHLY_KEYS = new Set([
  'doneDevos','doneGames','journal','customPromises','favoritePromises','devoNotes',
  'momentNotes','momentPrayed','momentDecisions','gameResponses','prayers','specialPrayers',
  'unlockedBadges','promiseBoxToday','favPromises','journalEntries','diaryEntries','letters',
  'cartas','reflections','momentosNotas','prayedDays','oracionesCompletadas'
]);
const SHARED_KEYS = new Set(['bibleDone']);
function storageKey(k){
  if(MONTHLY_KEYS.has(k)) return STORAGE_PREFIX+k;
  if(SHARED_KEYS.has(k)) return 'jardin:shared:'+k;
  return 'jardin:settings:'+k;
}
function safeParse(raw,f){try{return raw===null?f:(JSON.parse(raw) ?? f)}catch(e){return f}}
function get(k,f){return safeParse(localStorage.getItem(storageKey(k)),f)}
function set(k,v){localStorage.setItem(storageKey(k),JSON.stringify(v))}
function getEditionData(edition,k,f){return window.JARDIN_APP?.getEdition(edition,k,f) ?? f}
function setEditionData(edition,k,v){if(window.JARDIN_APP)window.JARDIN_APP.setEdition(edition,k,v)}
function migrateAugustStorage(){
  const legacyMonthly=[...MONTHLY_KEYS];
  legacyMonthly.forEach(k=>{
    const target=storageKey(k);
    if(localStorage.getItem(target)!==null)return;
    const candidates=['agosto2026_'+k,k];
    for(const oldKey of candidates){
      const value=localStorage.getItem(oldKey);
      if(value!==null){localStorage.setItem(target,value);break;}
    }
  });
  SHARED_KEYS.forEach(k=>{
    const target=storageKey(k);
    if(localStorage.getItem(target)===null&&localStorage.getItem(k)!==null)
      localStorage.setItem(target,localStorage.getItem(k));
  });
  localStorage.setItem('jardin:storage-schema',String(STORAGE_SCHEMA_VERSION));
}
migrateAugustStorage();
function el(id){return document.getElementById(id)}
function show(id){if(id==='esperanza')setTimeout(renderHopeBank,0);if(id==='promesas')setTimeout(initializePromiseBox,0);if(id==='insignias')setTimeout(renderBadges,0);if(id==='biblioteca')setTimeout(updateLibraryProgress,0);if(id==='certificado')setTimeout(updateCertificateUnlock,0);document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active')); const target=el(id); if(target) target.classList.add('active'); if(id==='devocional')renderDevos(); if(id==='juegos')renderGames(); if(id==='calendario')renderCalendar(); if(id==='promesas')renderPromises(); if(id==='anio')renderBibleYear(); if(id==='progreso')renderProgress(); if(id==='diario')renderJournal(); window.scrollTo({top:0,behavior:'smooth'})}
function renderDevos(){
  const doneRaw=get('doneDevos',[]);
  const prayedRaw=get('momentPrayed',[]);
  const decisions=get('momentDecisions',{})||{};
  const notes=get('momentNotes',{})||{};
  const done=Array.isArray(doneRaw)?doneRaw.map(Number).filter(n=>Number.isInteger(n)):[];
  const prayed=Array.isArray(prayedRaw)?prayedRaw.map(Number).filter(n=>Number.isInteger(n)):[];
  const cards=document.querySelectorAll('#devoBox .momentDayCard');

  cards.forEach((card,i)=>{
    const completed=done.includes(i);
    const inProgress=!completed && (prayed.includes(i) || Boolean(decisions[i]) || Boolean(notes[i]));
    card.classList.toggle('done',completed);
    card.classList.toggle('inProgress',inProgress);

    const status=card.querySelector('.momentStatus');
    const bloom=card.querySelector('.momentDayBloom');
    const button=card.querySelector('button.primary');

    if(status)status.textContent=completed?'Completado ✓':(inProgress?'En progreso':'Por comenzar');
    if(bloom)bloom.textContent=completed?'🌸':(inProgress?'🌷':'🌱');
    if(button)button.textContent=completed?'Volver a leer':(inProgress?'Continuar mi momento':'Comenzar mi momento');

    let decision=card.querySelector('.momentDecisionPreview');
    if(decisions[i]){
      if(!decision){
        decision=document.createElement('span');
        decision.className='momentDecisionPreview';
        card.insertBefore(decision,button);
      }
      decision.textContent=decisions[i];
    }else if(decision){
      decision.remove();
    }
  });
}
let activeMoment=0, activeMomentStep=0;
const momentChoices=['Hoy confiaré','Hoy perdonaré','Hoy descansaré en Dios','Hoy seré agradecida','Hoy obedeceré'];
function openMoment(i,step=0){activeMoment=i;activeMomentStep=step; const modal=el('momentModal'); if(modal){modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('momentOpen')} renderMomentStep()}
function closeMoment(){const modal=el('momentModal');if(modal){modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}document.body.classList.remove('momentOpen');renderDevos()}
function momentNext(){if(activeMomentStep<4){activeMomentStep++;renderMomentStep()}else finishMoment()}
function momentBack(){if(activeMomentStep>0){activeMomentStep--;renderMomentStep()}}
function saveMomentNote(i){let notes=get('momentNotes',{});notes[i]=el('momentHeartNote')?.value||'';set('momentNotes',notes)}
function markMomentPrayed(i){let a=get('momentPrayed',[]);if(!a.includes(i))a.push(i);set('momentPrayed',a);renderMomentStep();setTimeout(()=>{const f=el('prayerFlower');if(f)f.classList.add('bloom')},40)}
function chooseMomentDecision(i,value){let d=get('momentDecisions',{});d[i]=value;set('momentDecisions',d);renderMomentStep()}
function renderMomentStep(){
  const d=devos[activeMoment], i=activeMoment, box=el('momentContent');if(!d||!box)return;
  const notes=get('momentNotes',{}), prayed=get('momentPrayed',[]), decisions=get('momentDecisions',{});
  const dots=[0,1,2,3,4].map(n=>`<span class="${n===activeMomentStep?'active':n<activeMomentStep?'done':''}"></span>`).join('');
  let body='';
  if(activeMomentStep===0) body=`<div class="momentStep prepareStep"><div class="breathingOrb"><span>Respira</span></div><span class="momentKicker">PREPARA TU CORAZÓN</span><h2>Día ${d.day}: ${d.title}</h2><p>${d.before}</p><p class="breathGuide">Inhala paz · Exhala preocupación</p></div>`;
  if(activeMomentStep===1) body=`<div class="momentStep"><span class="momentKicker">DIOS ME HABLA HOY</span><h2>${d.title}</h2><blockquote class="momentScripture">“${d.promise.split(' — ')[0]}”<cite>${d.verse}</cite></blockquote><div class="momentReading"><p>${d.reflection}</p><h4>❤️ Para la mujer que hoy está…</h4><p>${d.womanToday}</p><h4>🌿 Conociendo más a Dios</h4><p>${d.knowingGod}</p></div></div>`;
  if(activeMomentStep===2) body=`<div class="momentStep"><span class="momentKicker">RESPONDO A SU VOZ</span><h2>Lo que Dios puso en mi corazón</h2><div class="heartPaper"><p>${d.question}</p><textarea id="momentHeartNote" placeholder="Escribe una frase sincera…">${escapeHtml(notes[i]||'')}</textarea><button class="secondary" onclick="saveMomentNote(${i})">Guardar mi frase</button></div><div class="momentSeed"><b>🌾 Semilla para recordar</b><p>${d.seed}</p></div></div>`;
  if(activeMomentStep===3) body=`<div class="momentStep center"><span class="momentKicker">MI ORACIÓN DE HOY</span><div id="prayerFlower" class="prayerFlower ${prayed.includes(i)?'bloom':''}">🌷</div><h2>${prayed.includes(i)?'Tu oración ha sido presentada':'Ora con calma'}</h2><p class="momentPrayer">${d.prayer}</p><button class="primary" onclick="markMomentPrayed(${i})">${prayed.includes(i)?'Ya oré ✓':'🙏 Ya oré'}</button></div>`;
  if(activeMomentStep===4) body=`<div class="momentStep"><span class="momentKicker">MI DECISIÓN DE HOY</span><h2>¿Qué semilla vas a vivir?</h2><p>${d.application}</p><div class="decisionGrid">${momentChoices.map(c=>`<button class="decisionChoice ${decisions[i]===c?'selected':''}" onclick="chooseMomentDecision(${i},'${c}')">${c}</button>`).join('')}</div><div class="momentPromise"><b>✨ Promesa para llevar contigo</b><p>${d.promise}</p></div></div>`;
  box.innerHTML=`<div class="momentProgress">${dots}</div>${body}<div class="momentNav">${activeMomentStep?'<button class="secondary" onclick="momentBack()">← Atrás</button>':'<span></span>'}<button class="primary" onclick="momentNext()">${activeMomentStep===4?'Finalizar mi encuentro':'Continuar →'}</button></div>`;
}
function finishMoment(){
  const i=activeMoment;
  let done=get('doneDevos',[]);
  done=done.map(Number).filter(Number.isInteger);
  if(!done.includes(i))done.push(i);
  set('doneDevos',[...new Set(done)]);
  const box=el('momentContent');
  if(box)box.innerHTML=`<div class="momentFinish"><div class="petals">🌸　🌷　🌸</div><span class="momentKicker">ENCUENTRO COMPLETADO</span><h2>Que Su paz permanezca contigo</h2><p class="momentFinishMessage">Has terminado tu momento con Dios de hoy. La semilla que recibiste seguirá creciendo en tu corazón. Que el Señor fortalezca tu fe, renueve tu esperanza y te acompañe en cada paso de este nuevo día.</p><button class="primary" onclick="closeMoment()">🌿 Volver a mi jardín</button></div>`;
  renderDevos();renderCalendar();renderProgress();updateLibraryProgress();
}
function toggleDevo(i){
  let a=get('doneDevos',[]);
  const wasDone=a.includes(i);
  a=wasDone?a.filter(x=>x!==i):[...a,i];
  set('doneDevos',a);
  renderDevos(); renderCalendar(); renderProgress();
  if(!wasDone) animateGardenWatering();
}
function filterGames(f){currentFilter=f; renderGames()}
