// PASO 8 — Ambiente dinámico según la hora local
function applyTimeAmbience(){
  const hour=new Date().getHours();
  let key='morning',icon='☀️',label='Mañana con Dios';
  if(hour>=5&&hour<8){key='dawn';icon='🌅';label='Amanecer con Dios';}
  else if(hour>=8&&hour<12){key='morning';icon='☀️';label='Mañana con Dios';}
  else if(hour>=12&&hour<17){key='afternoon';icon='🌤️';label='Tarde en Su presencia';}
  else if(hour>=17&&hour<20){key='sunset';icon='🌇';label='Atardecer con Dios';}
  else{key='night';icon='🌙';label='Noche de paz';}
  document.body.classList.remove('time-dawn','time-morning','time-afternoon','time-sunset','time-night');
  document.body.classList.add('time-'+key);
  document.documentElement.style.colorScheme=key==='night'?'dark':'light';
}
document.addEventListener('DOMContentLoaded',()=>{
  applyTimeAmbience();
  setInterval(applyTimeAmbience,60000);
});


// PASO 9 — Caja de Promesas interactiva
let revealedPromise=null;

function promiseForToday(){
  const now=new Date();
  const dateKey=`${now.getFullYear()}-${now.getMonth()+1}-${now.getDate()}`;
  const saved=get('promiseBoxToday',null);
  if(saved&&saved.dateKey===dateKey&&saved.promise)return saved.promise;
  const seed=(now.getFullYear()*372)+(now.getMonth()+1)*31+now.getDate();
  const p=promiseLibrary[seed%promiseLibrary.length];
  set('promiseBoxToday',{dateKey,promise:p});
  return p;
}

function openPromiseBox(){
  const scene=el('promiseBoxScene');
  if(!scene||scene.classList.contains('open'))return;
  revealedPromise=promiseForToday();
  if(el('promiseRevealText'))el('promiseRevealText').textContent='“'+revealedPromise.text+'”';
  if(el('promiseRevealRef'))el('promiseRevealRef').textContent=revealedPromise.ref;
  if(el('promiseRevealCategory'))el('promiseRevealCategory').textContent=(revealedPromise.cat||'PROMESA DEL DÍA').toUpperCase();
  scene.classList.add('open');
  createPromiseSparkles();
}

function resetPromiseBox(){
  const scene=el('promiseBoxScene');
  if(scene)scene.classList.remove('open');
}

function createPromiseSparkles(){
  const scene=el('promiseBoxScene');if(!scene)return;
  const symbols=['✨','🌸','•','✦'];
  for(let i=0;i<22;i++){
    const s=document.createElement('span');
    s.className='promiseSpark';
    s.textContent=symbols[i%symbols.length];
    s.style.left=(45+Math.random()*10)+'%';
    s.style.top=(44+Math.random()*8)+'%';
    s.style.setProperty('--spark-x',(Math.random()*260-130)+'px');
    s.style.animationDelay=(Math.random()*.5)+'s';
    scene.appendChild(s);
    setTimeout(()=>s.remove(),2400);
  }
}

function saveRevealedPromise(){
  const p=revealedPromise||promiseForToday();
  let fav=get('favPromises',[])||[];
  if(!fav.some(x=>x.ref===p.ref&&x.text===p.text)){
    fav.push(p);set('favPromises',fav);
    renderPromises();
    alert('Promesa guardada en tus favoritas 💜');
  }else alert('Esta promesa ya está en tus favoritas 💜');
}

async function shareRevealedPromise(){
  const p=revealedPromise||promiseForToday();
  const text=`🌸 Promesa para hoy\n\n“${p.text}”\n${p.ref}\n\nJardín de Oración · Agosto 2026`;
  try{
    if(navigator.share)await navigator.share({title:'Mi promesa de hoy',text});
    else if(navigator.clipboard){await navigator.clipboard.writeText(text);alert('La promesa fue copiada.');}
  }catch(e){}
}

function initializePromiseBox(){
  const p=promiseForToday();
  revealedPromise=p;
  if(el('promiseRevealText'))el('promiseRevealText').textContent='“'+p.text+'”';
  if(el('promiseRevealRef'))el('promiseRevealRef').textContent=p.ref;
  if(el('promiseRevealCategory'))el('promiseRevealCategory').textContent=(p.cat||'PROMESA DEL DÍA').toUpperCase();
}
document.addEventListener('DOMContentLoaded',()=>setTimeout(initializePromiseBox,150));


