// Certificado desbloqueable — requiere completar los 31 devocionales
function updateCertificateUnlock(){
  const completed=[...new Set(get('doneDevos',[]))].filter(i=>Number.isInteger(i)&&i>=0&&i<31).length;
  const unlocked=completed>=31;
  const lock=el('certificateLockPanel');
  const content=el('certificateUnlockedContent');
  const celebration=el('certificateCelebration');
  const bar=el('certificateUnlockBar');
  const text=el('certificateUnlockText');
  const status=el('certificateStatus');

  if(bar)bar.style.width=Math.min(100,Math.round(completed/31*100))+'%';
  if(text)text.textContent=`${completed} de 31 devocionales completados`;
  if(lock)lock.hidden=unlocked;
  if(content)content.hidden=!unlocked;

  const wasCelebrated=localStorage.getItem('jardin:agosto2026:certificateCelebrated')==='true';
  if(celebration){
    celebration.hidden=!unlocked||wasCelebrated;
    if(unlocked&&!wasCelebrated){
      localStorage.setItem('jardin:agosto2026:certificateCelebrated','true');
      setTimeout(()=>{if(celebration)celebration.hidden=true;},7000);
    }
  }

  if(status)status.textContent=unlocked
    ?'Tu Certificado de Restauración está desbloqueado y listo para personalizar. 🌸'
    :`Completa los 31 devocionales para desbloquearlo. Llevas ${completed}/31.`;

  const nameInput=el('certificateName');
  const printButton=el('certificatePrintButton');
  if(nameInput)nameInput.disabled=!unlocked;
  if(printButton)printButton.disabled=!unlocked;
}

function printAugustCertificate(){
  const completed=[...new Set(get('doneDevos',[]))].filter(i=>Number.isInteger(i)&&i>=0&&i<31).length;
  if(completed<31){
    alert(`Tu certificado se desbloqueará cuando completes los 31 devocionales. Llevas ${completed}/31. 🌱`);
    return;
  }
  const name=(el('certificateName')?.value||'').trim();
  if(!name){
    alert('Escribe tu nombre antes de imprimir o guardar el certificado. 🌸');
    el('certificateName')?.focus();
    return;
  }
  updateAugustCertificate();
  window.print();
}


